settings.custom_css:
.heroh4 h4{
    font-family: "Montserrat", Sans-serif;
    font-size: 16px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #162232;
}

.heroh4 span{
    color:#34A853;
}

.elementor-widget-nav-menu.footermenu .elementor-nav-menu--main ul li {
  margin: 0 0 12px 0;
}
.elementor-widget-nav-menu.footermenu .elementor-nav-menu--main ul li a.elementor-item {
  font-family: "Open Sans";
  font-size: 13px;
  padding: 0;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.5);
  text-decoration: underline;
  transition: all .3s;
}
.elementor-widget-nav-menu.footermenu .elementor-nav-menu--main ul li a.elementor-item:hover {
  color: #fff;
}
.elementor-widget-nav-menu.footermenu .elementor-nav-menu--main ul li a.elementor-item:after {
  display: none;
}
